import {loadData} from './api.js';
import {num,stats,monthly,regional,filterBrands} from './data-utils.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stored(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(x=>typeof x==='string'):[];}catch{return [];}}
let data, year, compare=stored('tantan-compare').slice(0,3), saved=stored('tantan-saved');
let filters={query:'',category:'전체',region:'전국',sort:'stores'}, selectedRegion='서울', currentView='home';
const saveState=()=>{try{localStorage.setItem('tantan-compare',JSON.stringify(compare));localStorage.setItem('tantan-saved',JSON.stringify(saved));}catch{toast('이 브라우저에서는 저장을 사용할 수 없어요. 현재 화면에서는 유지됩니다.');}};
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
const brand=id=>data.brands.find(b=>b.id===id);
const imagePath=b=>`assets/${encodeURIComponent(b.image)}`;
const metric=(value,unit)=>value==null?'미제공':`${num(value)}<small>${unit}</small>`;
const count=v=>v==null?'미제공':num(v)+'개';
const money=v=>v==null?'미제공':`${num(Math.round(v/10000))}만원`;
const sample=()=>data.is_demo?'<span class="demo-label">● 예시 데이터</span>':`<span class="demo-label">${esc(data.source_label)}</span>`;
const yearSelect=()=>`<label><span class="sr-only">기준연도 </span><select data-action="year" aria-label="기준연도">${data.years.map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}년 기준</option>`).join('')}</select></label>`;
const regionSelect=(value=filters.region)=>`<select data-action="region" aria-label="지역 선택"><option>전국</option>${data.regions.map(r=>`<option ${r===value?'selected':''}>${esc(r)}</option>`).join('')}</select>`;
function updateControls(){
 $('#compare-count').textContent=compare.length;
 document.querySelectorAll('[data-compare]').forEach(el=>{const on=compare.includes(el.dataset.compare);el.classList.toggle('on',on);el.setAttribute('aria-pressed',String(on));el.innerHTML=`<span class="checkbox">✓</span>${on?'비교함에 담김':'비교 담기'}`;});
 document.querySelectorAll('[data-save]').forEach(el=>{const on=saved.includes(el.dataset.save);el.classList.toggle('on',on);el.setAttribute('aria-pressed',String(on));el.setAttribute('aria-label',`${brand(el.dataset.save)?.name} 관심 브랜드 ${on?'해제':'저장'}`);el.innerHTML=on?'♥':'♡';});
 $('#compare-tray').innerHTML=compare.length&&currentView!=='compare'?`<aside class="compare-bar" aria-label="브랜드 비교함"><strong>브랜드 비교 <span style="color:var(--lemon)">${compare.length}/3</span></strong><div class="tray-items">${compare.map(id=>`<span class="tray-item">${esc(brand(id).name)}<button data-remove="${esc(id)}" aria-label="${esc(brand(id).name)} 비교함에서 제거">×</button></span>`).join('')}</div><button class="tray-clear" data-action="clear-compare">비우기</button><a class="button lemon" href="#/compare">비교하기 ↗</a></aside>`:'';
}
function card(b){const s=stats(b,year);return `<article class="brand-card"><button class="save-btn" data-save="${esc(b.id)}" aria-label="관심 브랜드 저장">♡</button><a class="card-cover" href="#/brand/${encodeURIComponent(b.id)}"><img src="${imagePath(b)}" alt="${esc(b.category)} 분위기 참고 사진" loading="lazy"><span class="cover-brand">${esc(b.english_name)}</span></a><div class="card-body"><div class="card-subtitle">${esc(b.category)} · ${data.is_demo?'가상 브랜드':esc(data.source_label)}</div><h3><a href="#/brand/${encodeURIComponent(b.id)}">${esc(b.name)}</a></h3><dl class="card-data"><div><dt>평균 월 매출</dt><dd>${metric(monthly(s),'만원')}</dd></div><div><dt>${esc(filters.region)} 매장 수</dt><dd>${metric(regional(s,filters.region),'개')}</dd></div><div><dt>연간 개업</dt><dd class="up">${metric(s?.opened,'개')}</dd></div><div><dt>연간 폐업</dt><dd>${metric(s?.closed,'개')}</dd></div></dl></div><div class="card-footer"><button class="compare-toggle" data-compare="${esc(b.id)}"><span class="checkbox">✓</span>비교 담기</button><a href="#/brand/${encodeURIComponent(b.id)}">자세히 보기 ↗</a></div></article>`;}
function renderCards(){const rows=filterBrands(data.brands,{...filters,year,saved:currentView==='saved'?saved:null});$('#results-count').innerHTML=`총 <strong>${rows.length}개</strong> 브랜드`;$('#brand-grid').innerHTML=rows.length?rows.map(card).join(''):`<div class="empty"><h2>${currentView==='saved'?'관심 브랜드가 없어요':'조건에 맞는 브랜드가 없어요'}</h2><p>${currentView==='saved'?'브랜드 카드의 하트를 눌러 관심 브랜드를 모아보세요.':'검색어나 지역·업종 필터를 바꿔보세요.'}</p><button class="button" data-action="reset">${currentView==='saved'?'모든 브랜드 둘러보기':'필터 초기화'}</button></div>`;updateControls();}
function home(isSaved=false){
 currentView=isSaved?'saved':'home';
 $('#main').innerHTML=`${!isSaved?`<section class="hero"><div class="hero-inner"><div class="hero-copy"><span class="eyebrow">FCHA TANTAN · 2024—2025</span><h1>시작의 기준을,<br><em>탄탄하게.</em></h1><p>내게 맞는 프랜차이즈, 데이터로 비교하세요.</p><a class="button lemon" href="#brands" data-scroll="brands">브랜드 둘러보기 <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-block block-one"></div><div class="art-block block-two"></div><div class="art-block block-three"></div><span class="art-caption">BUILD YOUR NEXT.</span></div></div></section>`:''}<div class="container"><section class="section" id="brands"><div class="section-head"><div><span class="eyebrow">${isSaved?'MY COLLECTION':'FIND YOUR BRAND'}</span><h2>${isSaved?'마음에 담아둔 브랜드':'어떤 시작을 찾고 있나요?'}</h2></div><form class="search-form" id="search-form"><span aria-hidden="true">⌕</span><input name="query" value="${esc(filters.query)}" aria-label="브랜드명 검색" placeholder="브랜드명 검색"><button aria-label="검색" type="submit">↵</button></form></div><div class="filter-panel"><div class="filter-row"><div class="chips">${['전체','카페','치킨','편의점','미용실'].map(c=>`<button class="chip ${filters.category===c?'active':''}" data-category="${c}" aria-pressed="${filters.category===c}">${c}</button>`).join('')}</div><div class="selects">${regionSelect()}${yearSelect()}</div></div><div class="filter-meta"><span>${sample()} <span class="filter-scope">매출·개폐업: 전국 · 매장: 선택 지역</span></span><button class="reset" data-action="reset">↻ 초기화</button></div></div><div class="result-toolbar"><span id="results-count"></span><select data-action="sort" aria-label="정렬 방식">${[['stores','매장 수 많은 순'],['sales','평균 월 매출 높은 순'],['opened','신규 개업 많은 순'],['closed','폐업 수 적은 순'],['name','브랜드 이름순']].map(([v,t])=>`<option value="${v}" ${v===filters.sort?'selected':''}>${t}</option>`).join('')}</select></div><div class="cards" id="brand-grid"></div><p class="data-note">ⓘ ${year}년 기준 · 평균 월 매출은 가맹점 평균 연매출을 12개월로 나눈 값이며, 신규 창업점의 예상 매출이나 순이익이 아닙니다.<br>${data.is_demo?'모든 수치와 브랜드는 가상이며, 사진은 업종을 표현한 참고 이미지입니다.':'출처: '+esc(data.source_label)} </p></section></div>${!isSaved?`<section class="insight-band"><div class="container insight-grid"><a class="insight-card" href="#/regions"><div><span class="eyebrow">LOCATION</span><h3>지역에서 기회를 찾다.</h3></div><span class="insight-arrow">↗</span></a><a class="insight-card" href="#/guide"><div><span class="eyebrow">DATA GUIDE</span><h3>숫자의 기준을 읽다.</h3></div><span class="insight-arrow">↗</span></a></div></section>`:''}`;
 renderCards();
}
function bars(items){const max=Math.max(1,...items.map(x=>x[1]??0));return `<div class="bar-list">${items.map(([r,v])=>`<div class="bar-row"><span>${esc(r)}</span><div class="bar-track"><div class="bar-fill" style="width:${(v??0)/max*100}%"></div></div><span class="bar-value">${count(v)}</span></div>`).join('')}</div>`;}
function trend(b){const ss=[...b.stats].sort((a,b)=>a.year-b.year),max=Math.max(1,...ss.flatMap(s=>[s.opened??0,s.closed??0]));return `<div class="legend"><span>신규 개업</span><span>폐업</span></div><div class="chart" role="img" aria-label="${esc(ss.map(s=>`${s.year}년 개업 ${num(s.opened)}개, 폐업 ${num(s.closed)}개`).join('. '))}">${ss.map(s=>`<div class="chart-group"><div class="chart-bar" style="height:${(s.opened??0)/max*85}%"><span>${num(s.opened)}</span></div><div class="chart-bar secondary" style="height:${(s.closed??0)/max*85}%"><span>${num(s.closed)}</span></div><span class="chart-year">${s.year}년</span></div>`).join('')}</div>`;}
function detail(id){const b=brand(id);currentView='detail';if(!b){$('#main').innerHTML='<div class="container section"><div class="empty"><h2>브랜드를 찾을 수 없어요.</h2><p>주소를 확인하거나 브랜드 목록으로 돌아가세요.</p><a class="button" href="#/">브랜드 둘러보기</a></div></div>';updateControls();return;}
 const s=stats(b,year),regions=Object.entries(s?.regions||{}).sort((a,b)=>b[1]-a[1]);
 $('#main').innerHTML=`<div class="container"><div class="page-header"><div class="breadcrumb"><a href="#/">브랜드 탐색</a> / ${esc(b.category)} / ${esc(b.name)}</div><div class="page-title-row"><a class="back-link" href="#/">← 브랜드 목록으로</a><div class="page-tools">${sample()}${yearSelect()}<button class="button outline small" data-compare="${esc(b.id)}">비교 담기</button><button class="button outline small" data-save="${esc(b.id)}">♡</button></div></div><section class="detail-hero" style="background:${esc(b.color)}33"><div class="detail-intro"><span class="brand-monogram">${esc(b.name.slice(0,1))}</span><span class="eyebrow" style="margin:20px 0 0">${esc(b.english_name)}</span><h1>${esc(b.name)}</h1><p>${esc(b.tagline)}</p></div><img class="detail-photo" src="${imagePath(b)}" alt="${esc(b.category)} 참고 사진"></section></div><nav class="detail-tabs" aria-label="브랜드 상세 목차"><a href="#overview" data-scroll="overview">브랜드 한눈에</a><a href="#trend" data-scroll="trend">개·폐업 현황</a><a href="#distribution" data-scroll="distribution">지역별 매장</a><a href="#cost" data-scroll="cost">창업비용</a></nav><section class="section" id="overview"><div class="section-head"><div><h2>숫자로 살펴보는 ${esc(b.name)}</h2><p>${year}년 · 전국 가맹점 기준</p></div>${sample()}</div><div class="metrics"><article class="metric"><span class="label">연말 전체 매장</span><strong>${metric(s?.stores,'개')}</strong><p>선택 연도 말 영업 매장 수</p></article><article class="metric"><span class="label">연간 신규 개업</span><strong class="up">${metric(s?.opened,'개')}</strong><p>선택 연도 내 신규 개업 합계</p></article><article class="metric"><span class="label">연간 폐업</span><strong>${metric(s?.closed,'개')}</strong><p>선택 연도 내 폐업 합계</p></article><article class="metric highlight"><span class="label">가맹점 평균 월 매출</span><strong>${metric(monthly(s),'만원')}</strong><p>평균 연매출 ÷ 12 · 전국 기준</p></article></div><div class="notice">${esc(b.description)}<br>※ 매출은 수익을 보장하지 않으며, 폐업 건수만으로 브랜드의 위험도를 판단할 수 없습니다.</div></section><div class="detail-grid"><section class="panel" id="trend"><h2>개업과 폐업, 흐름을 확인하세요</h2><p class="subtitle">연도별 신규 개업·폐업 건수 · 단위: 개</p>${trend(b)}<p class="data-note">개업·폐업은 각 연도 발생 건수입니다. 운영 매장 총수와는 다른 지표입니다.</p></section><section class="panel" id="distribution"><h2>어느 지역에 많을까요?</h2><p class="subtitle">${year}년 매장 수 상위 7개 지역</p>${bars(regions.slice(0,7))}<a class="text-link" href="#/regions">전체 지역 브랜드 비교하기 ↗</a></section></div><details class="panel" style="margin:24px 0"><summary>전체 17개 지역 매장 수 확인</summary>${bars(data.regions.map(r=>[r,s?.regions[r]??null]))}</details><div class="detail-grid" id="cost"><section class="panel"><h2>창업비용을 꼼꼼하게</h2><p class="subtitle">${b.area_sqm}㎡ 기준 · 예시 견적 · 단위: 만원</p><div class="cost-list">${Object.entries(b.costs).map(([k,v])=>`<div class="cost-line"><span>${esc(k)}</span><b>${money(v)}</b></div>`).join('')}</div><div class="cost-total"><span>예시 초기 비용 합계</span><strong>${money(b.initial_cost_krw)}</strong></div></section><section class="panel"><span class="eyebrow">CHECK BEFORE YOU START</span><h2>숫자 뒤의 조건도 살펴보세요</h2><p class="subtitle">같은 브랜드라도 실제 창업비용과 매출은 달라질 수 있어요.</p><div class="notice">• 임대보증금·권리금·부가세·별도 공사비는 예시 비용에서 제외했습니다.<br>• 상권, 매장 면적, 운영 방식에 따라 비용이 달라집니다.<br>• 평균 월 매출은 기존 가맹점의 연매출 환산값으로, 신규 매장의 예상 매출이 아닙니다.<br>• 실제 계약 전에는 정보공개서와 본사 견적을 확인하세요.</div><p class="data-note">${esc(data.source_label)} · 갱신일 ${esc(data.updated_at)}</p><a class="text-link" href="#/guide">지표 정의 자세히 보기 ↗</a></section></div></div>`;updateControls();}
function comparison(){currentView='compare';const bs=compare.map(brand).filter(Boolean);$('#main').innerHTML=`<div class="container comparison-section"><div class="page-header"><span class="eyebrow">SIDE BY SIDE</span><div class="page-title-row"><div><h1>나란히 놓으면, 선택이 선명해져요.</h1><p>최대 3개 브랜드를 같은 기준으로 비교해 보세요.</p></div><div class="page-tools">${yearSelect()}${sample()}</div></div></div>${bs.length?`<div class="compare-actions"><span class="muted" style="font-size:15px">${bs.length}개 브랜드 선택 · 전국 기준</span><div class="page-tools"><button class="button outline small" data-action="export">CSV 내려받기 ↓</button><a class="button small" href="#/">브랜드 추가 +</a></div></div><div class="table-wrap"><table class="compare-table"><thead><tr><th>비교 항목</th>${bs.map(b=>`<th><img src="${imagePath(b)}" alt="${esc(b.category)} 참고 사진"><h3><a href="#/brand/${esc(b.id)}">${esc(b.name)} ↗</a></h3><p>${esc(b.category)}</p><button class="reset" data-remove="${esc(b.id)}" aria-label="${esc(b.name)} 비교에서 제거">비교에서 제거 ×</button></th>`).join('')}</tr></thead><tbody>${compareRows(bs)}</tbody></table></div><p class="data-note">평균 월 매출은 연매출 ÷ 12 환산값입니다. 단순 수치 비교이며 순위·수익성·안전성을 보장하지 않습니다.<br>${data.is_demo?'브랜드와 모든 수치는 시연용 가상 데이터입니다.':'출처: '+esc(data.source_label)}</p>`:`<div class="empty"><h2>어떤 브랜드가 궁금한가요?</h2><p>브랜드 카드에서 ‘비교 담기’를 누르면 나란히 확인할 수 있어요.</p><a class="button" href="#/">브랜드 선택하러 가기 ↗</a></div>`}</div>`;updateControls();}
function compareRows(bs){const rows=[['연말 매장 수',b=>count(stats(b,year)?.stores)],['연간 신규 개업',b=>count(stats(b,year)?.opened)],['연간 폐업',b=>count(stats(b,year)?.closed)],['평균 월 매출',b=>monthly(stats(b,year))==null?'미제공':num(monthly(stats(b,year)))+'만원'],['예시 창업비용',b=>money(b.initial_cost_krw)],['기준 면적',b=>b.area_sqm+'㎡'],...data.regions.map(r=>[`${r} 매장 수`,b=>count(stats(b,year)?.regions[r])])];return rows.map(([label,fn],i)=>`<tr><td>${label}</td>${bs.map(b=>`<td class="${i===3?'best':''}"><span class="${i<5?'big-number':''}">${esc(fn(b))}</span></td>`).join('')}</tr>`).join('');}
function regions(){currentView='regions';const entries=data.brands.map(b=>({b,s:stats(b,year)})).sort((a,b)=>(b.s?.regions[selectedRegion]??0)-(a.s?.regions[selectedRegion]??0));const total=entries.reduce((t,{s})=>t+(s?.regions[selectedRegion]??0),0);
 $('#main').innerHTML=`<div class="container"><div class="page-header"><span class="eyebrow">LOCATION INSIGHT</span><div class="page-title-row"><div><h1>내가 시작하고 싶은 지역은?</h1><p>지역을 선택하고, 브랜드별 매장 분포를 확인하세요.</p></div><div class="page-tools">${yearSelect()}${sample()}</div></div></div><div class="region-layout"><aside class="panel"><h2>지역 선택</h2><p class="subtitle">전국 17개 시·도</p><div class="region-tiles">${data.regions.map(r=>`<button class="region-tile ${r===selectedRegion?'active':''}" data-region-tile="${esc(r)}" aria-pressed="${r===selectedRegion}">${esc(r)}<b>${num(data.brands.reduce((t,b)=>t+(stats(b,year)?.regions[r]??0),0))}개</b></button>`).join('')}</div><p class="data-note">표시된 브랜드의 매장 수를 합산했습니다. 해당 지역 전체 프랜차이즈 매장 수는 아닙니다.</p></aside><section><div class="region-summary"><span>${esc(selectedRegion)} · 등록 브랜드 매장 합계</span><strong>${num(total)}<small style="font-size:16px"> 개</small></strong><small>${year}년 말 기준 · ${entries.filter(x=>(x.s?.regions[selectedRegion]??0)>0).length}개 브랜드 ${data.is_demo?'· 예시 데이터':''}</small></div><div class="table-wrap"><table><thead><tr><th>브랜드</th><th>${esc(selectedRegion)} 매장</th><th>전국 중 비중</th><th>비교</th></tr></thead><tbody>${entries.map(({b,s})=>`<tr><td><a class="brand-cell" href="#/brand/${esc(b.id)}"><span class="table-icon" style="background:${esc(b.color)}">${esc(b.name[0])}</span>${esc(b.name)}</a></td><td><b>${count(s?.regions[selectedRegion])}</b></td><td>${s?.stores?((s.regions[selectedRegion]??0)/s.stores*100).toFixed(1)+'%':'미제공'}</td><td><button class="compare-toggle" data-compare="${esc(b.id)}">비교 담기</button></td></tr>`).join('')}</tbody></table></div><p class="data-note">매장 수만으로 상권의 수요나 경쟁 강도를 판단할 수 없습니다. 유동인구·임대료·주변 업종 등 추가 분석이 필요합니다.</p></section></div></div>`;updateControls();}
function guide(){currentView='guide';$('#main').innerHTML=`<div class="container"><div class="page-header"><span class="eyebrow">OUR DATA, YOUR CONFIDENCE</span><h1>숫자의 기준부터, 탄탄하게.</h1><p>무엇을 비교하고 있는지 알면 더 나은 질문을 할 수 있어요.</p></div><div class="notice">${sample()} ${data.is_demo?'현재 화면은 가상 브랜드 8개와 2024·2025년 예시 통계로 구성되어 있습니다. 실제 창업 판단에 사용할 수 없습니다.':esc(data.source_label)}<br>갱신일: ${esc(data.updated_at)} · 금액 표시: 만원 · 내부 금액 단위: 원</div><div class="guide-grid">${[
 ['01 / OPENINGS','총 창업 개수는 어떻게 보나요?','이 화면의 신규 개업 수는 선택한 1년 동안 전국에서 발생한 개업 건수의 합계입니다. 브랜드 설립 이후 누적 창업 수가 아닙니다. 신규 계약 건수만 있는 자료는 실제 개업 수로 바꾸어 표시하면 안 됩니다.'],
 ['02 / CLOSURES','폐업과 계약 종료는 달라요.','폐업 수는 선택 연도에 영업을 종료한 매장 수입니다. 정보공개서의 계약종료·계약해지를 단순 합산해 실제 폐업으로 간주하지 않습니다. 실제 폐업 자료가 없는 경우 미제공으로 남겨야 합니다.'],
 ['03 / REVENUE','평균 월 매출은 예상 수익인가요?','아닙니다. 가맹점 평균 연매출을 12로 나눈 참고값입니다. 신규 창업점의 예상 매출이나 순이익을 의미하지 않습니다. 임대료·인건비·원재료비 등이 차감되지 않았습니다.'],
 ['04 / STORES','매장 수는 어떤 시점인가요?','선택한 연도 말의 가맹점 수를 사용합니다. 직영점 포함 여부와 집계 시점을 통일해야 브랜드 간 비교가 가능합니다. 지역 화면의 합계는 현재 등록된 브랜드만 합산한 값입니다.'],
 ['05 / COSTS','창업비용에 무엇이 포함되나요?','예시 비용은 가맹비·교육비·보증금·인테리어·설비 및 기타 비용으로 구성했습니다. 임대보증금·권리금·부가세·별도 공사는 제외했습니다. 실제 도입 시 기준 면적과 포함 항목, 견적 시점을 함께 확인해야 합니다.'],
 ['06 / SOURCES','실제 데이터를 연결할 때','브랜드별 공시와 지역 매장 자료를 같은 연도·브랜드 식별자로 연결합니다. 지표의 원문 정의와 출처, 기준연도, 갱신일을 보존해야 합니다. 미수집 값은 0이 아닌 ‘미제공’으로 표시합니다.']
 ].map(([n,h,p])=>`<article class="panel"><span class="eyebrow">${n}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</div></div>`;updateControls();}
function render(){const route=location.hash.replace(/^#\/?/,'').split('/');document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(route[0]||'home')));if(route[0]==='brand')detail(decodeURIComponent(route[1]||''));else if(route[0]==='compare')comparison();else if(route[0]==='regions')regions();else if(route[0]==='guide')guide();else home(route[0]==='saved');document.title=currentView==='detail'?`${brand(decodeURIComponent(route[1]||''))?.name||'브랜드'} | 프차 탄탄`:'프차 탄탄 — 탄탄한 선택의 기준';}
function exportCSV(){const header=['데이터 구분','기준연도','브랜드','전국 매장 수','연간 개업 수','연간 폐업 수','평균 월 매출(만원)','예시 창업비용(원)'];const rows=compare.map(id=>{const b=brand(id),s=stats(b,year);return [data.is_demo?'가상 예시':'실제 데이터',year,b.name,s?.stores,s?.opened,s?.closed,monthly(s),b.initial_cost_krw];});const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const blob=new Blob(['\ufeff'+[header,...rows].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`프차탄탄_브랜드비교_${year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('비교 데이터를 CSV로 내려받았어요.');}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.action==='retry'){boot();return;}if(!data)return;
 if(el.dataset.scroll){e.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}
 if(el.dataset.compare){const id=el.dataset.compare;if(compare.includes(id))compare=compare.filter(x=>x!==id);else{if(compare.length>=3){toast('최대 3개 브랜드까지 비교할 수 있어요. 기존 브랜드를 먼저 빼주세요.');return;}compare.push(id);}saveState();updateControls();return;}
 if(el.dataset.save){const id=el.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];saveState();if(currentView==='saved')renderCards();else updateControls();return;}
 if(el.dataset.remove){compare=compare.filter(x=>x!==el.dataset.remove);saveState();if(currentView==='compare')comparison();else updateControls();return;}
 if(el.dataset.category){filters.category=el.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===filters.category);b.setAttribute('aria-pressed',String(b.dataset.category===filters.category));});renderCards();return;}
 if(el.dataset.regionTile){selectedRegion=el.dataset.regionTile;regions();return;}
 const action=el.dataset.action;if(action==='clear-compare'){compare=[];saveState();updateControls();}else if(action==='reset'){filters={query:'',category:'전체',region:'전국',sort:'stores'};if(currentView==='saved')location.hash='#/';else home();}else if(action==='export')exportCSV();else if(action==='retry')boot();
});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();filters.query=new FormData(e.target).get('query').trim();renderCards();}});
document.addEventListener('input',e=>{if(e.target.name==='query'){filters.query=e.target.value.trim();renderCards();}});
document.addEventListener('change',e=>{const action=e.target.dataset.action;if(action==='year'){year=Number(e.target.value);render();}else if(action==='region'){filters.region=e.target.value;renderCards();}else if(action==='sort'){filters.sort=e.target.value;renderCards();}});
window.addEventListener('hashchange',()=>{if(data){render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}});
async function boot(){try{data=await loadData();year=data.years[0] ?? new Date().getFullYear();compare=compare.filter(id=>brand(id));saved=saved.filter(id=>brand(id));render();}catch(e){$('#main').innerHTML=`<div class="container section"><div class="empty"><h2>데이터를 불러오지 못했어요.</h2><p>${esc(e.message)}<br>인터넷 연결과 데이터 서버 상태를 확인해 주세요.</p><button class="button" data-action="retry">다시 시도</button></div></div>`;}}
boot();
